package dev.isylxnt.duskcontracts.api.event;
import dev.isylxnt.duskcontracts.domain.ClaimType; import org.bukkit.event.Event; import org.bukkit.event.HandlerList; import java.util.UUID;
public final class ContractClaimedEvent extends Event { private static final HandlerList HANDLERS=new HandlerList(); private final UUID claimId; private final UUID playerId; private final ClaimType type; public ContractClaimedEvent(UUID claimId,UUID playerId,ClaimType type,boolean async){super(async);this.claimId=claimId;this.playerId=playerId;this.type=type;} public UUID claimId(){return claimId;} public UUID playerId(){return playerId;} public ClaimType type(){return type;} @Override public HandlerList getHandlers(){return HANDLERS;} public static HandlerList getHandlerList(){return HANDLERS;} }
